        treeSize: json['treeSize'] as int,
        rootHash: json['rootHash'] as String,
        issuedAt: json['issuedAt'] as String,
      );

  final ElectionId electionId;
  final int treeSize;

  /// The RFC 9162 Merkle tree hash (SHA-256) of the first `treeSize` entries, as a
  /// multihash.
  final DigestMultibase rootHash;
  final String issuedAt;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'electionId': electionId,
        'treeSize': treeSize,
        'rootHash': rootHash,
        'issuedAt': issuedAt,
      };
}

/// An election's result, computable by anyone who can read its board from the board
/// and the registration alone (VTI-VOT-070).
class ElectionResult {
  const ElectionResult({
    required this.electionId,
    required this.manifestDigest,
    required this.ballotsCounted,
    required this.questions,
    required this.head,
  });

  /// Read this payload from a decoded JSON object.
  factory ElectionResult.fromJson(Map<String, dynamic> json) => ElectionResult(
        electionId: json['electionId'] as String,
        manifestDigest: json['manifestDigest'] as String,
        ballotsCounted: json['ballotsCounted'] as int,
        questions: (json['questions'] as List<dynamic>)
            .map((e) => QuestionResult.fromJson(e as Map<String, dynamic>))
            .toList(),
        head: BoardHead.fromJson(json['head'] as Map<String, dynamic>),
      );

  final ElectionId electionId;
  final DigestMultibase manifestDigest;
  final int ballotsCounted;
  final List<QuestionResult> questions;

  /// The head of the board as it stood at close: the result counts exactly its entries.
  final BoardHead head;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'electionId': electionId,
        'manifestDigest': manifestDigest,
        'ballotsCounted': ballotsCounted,
        'questions': questions.map((e) => e.toJson()).toList(),
        'head': head.toJson(),
      };
}

/// An idea's election as a board shows it (VTI-BRD-033): never who took a ticket or
/// cast a ballot.
class IdeaElection {
  const IdeaElection({
    required this.electionId,
    required this.state,
    this.ballotsOnBoard,
    this.boardHeadIssuedAt,
    this.result,
    this.certified,
  });

  /// Read this payload from a decoded JSON object.
  factory IdeaElection.fromJson(Map<String, dynamic> json) => IdeaElection(
        electionId: json['electionId'] as String,
        state: ElectionState(json['state'] as String),
        ballotsOnBoard: json['ballotsOnBoard'] as int?,
        boardHeadIssuedAt: json['boardHeadIssuedAt'] as String?,
        result: json['result'] == null
            ? null
            : ElectionResult.fromJson(json['result'] as Map<String, dynamic>),
        certified: json['certified'] as bool?,
      );

  final ElectionId electionId;
  final ElectionState state;

  /// The ballot box's latest board head's ballot count, where its board is public
  /// (VTI-VOT-052); absent otherwise. Counts ballots, not voters, where a later ballot
  /// replaces an earlier one.
  final int? ballotsOnBoard;

  /// When the head `ballotsOnBoard` was read from was issued.
  final String? boardHeadIssuedAt;

  /// Present once the election is tallied.
  final ElectionResult? result;

  /// Present with `result`: whether the community certified it (VTI-VOT-071).
  final bool? certified;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'electionId': electionId,
        'state': state.value,
        if (ballotsOnBoard != null) 'ballotsOnBoard': ballotsOnBoard!,
        if (boardHeadIssuedAt != null) 'boardHeadIssuedAt': boardHeadIssuedAt!,
        if (result != null) 'result': result!.toJson(),
        if (certified != null) 'certified': certified!,
      };
}

/// IdeaOpeningRefusal, generated from its schema.
class IdeaOpeningRefusal {
  const IdeaOpeningRefusal({
    required this.code,
    required this.refusedAt,
  });

  /// Read this payload from a decoded JSON object.
  factory IdeaOpeningRefusal.fromJson(Map<String, dynamic> json) =>
      IdeaOpeningRefusal(
        code: json['code'] as String,
        refusedAt: json['refusedAt'] as String,
      );

  final String code;
  final String refusedAt;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'code': code,
        'refusedAt': refusedAt,
      };
}

/// Shown to facilitators only: an accepted idea whose election the ballot box has not
/// yet registered, so the idea is still `proposed` (VTI-BRD-031). `refusal` is the
/// ballot box's or community's refusal of the last attempt, after which the idea is no
/// longer being opened.
class IdeaOpening {
  const IdeaOpening({
    required this.electionId,
    required this.startedAt,
    this.refusal,
  });

  /// Read this payload from a decoded JSON object.
  factory IdeaOpening.fromJson(Map<String, dynamic> json) => IdeaOpening(
        electionId: json['electionId'] as String,
        startedAt: json['startedAt'] as String,
        refusal: json['refusal'] == null
            ? null
            : IdeaOpeningRefusal.fromJson(
                json['refusal'] as Map<String, dynamic>),
      );

  final ElectionId electionId;

  /// When the facilitator accepted the idea.
  final String startedAt;
  final IdeaOpeningRefusal? refusal;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'electionId': electionId,
        'startedAt': startedAt,
        if (refusal != null) 'refusal': refusal!.toJson(),
      };
}

/// A facilitator's decision on an idea: declining or merging it (VTI-BRD-013), or
/// selecting it or not (VTI-BRD-040). The deciding facilitator is not named to the
/// audience.
class IdeaDecision {
  const IdeaDecision({
    required this.decidedAt,
    this.reason,
    this.mergedInto,
    this.slotId,
    this.departsFromRule,
    this.ownIdea,
  });

  /// Read this payload from a decoded JSON object.
  factory IdeaDecision.fromJson(Map<String, dynamic> json) => IdeaDecision(
        decidedAt: json['decidedAt'] as String,
        reason: json['reason'] as String?,
        mergedInto: json['mergedInto'] as String?,
        slotId: json['slotId'] as String?,
        departsFromRule: json['departsFromRule'] as bool?,
        ownIdea: json['ownIdea'],
      );

  final String decidedAt;
  final Reason? reason;

  /// Present exactly when the idea is `merged`.
  final IdeaId? mergedInto;

  /// A `selected` idea's place in the board's timetable, where it has one.
  final Key? slotId;

  /// `selected` or `notSelected` only: whether the facilitator said the decision departs
  /// from the board's `selectionRule` (VTI-BRD-041); `reason` then says why.
  final bool? departsFromRule;

  /// Present when a facilitator decided their own idea because no other facilitator
  /// existed (VTI-BRD-013).
  final Object? ownIdea;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'decidedAt': decidedAt,
        if (reason != null) 'reason': reason!,
        if (mergedInto != null) 'mergedInto': mergedInto!,
        if (slotId != null) 'slotId': slotId!,
        if (departsFromRule != null) 'departsFromRule': departsFromRule!,
        if (ownIdea != null) 'ownIdea': ownIdea!,
      };
}

/// An idea as one caller may see it.
class Idea {
  const Idea({
    required this.ideaId,
    required this.boardId,
    required this.state,
    required this.title,
    required this.description,
    this.format,
    this.topic,
    required this.proposer,
    required this.proposedAt,
    required this.noteCount,
    this.election,
    this.opening,
    this.decision,
  });

  /// Read this payload from a decoded JSON object.
  factory Idea.fromJson(Map<String, dynamic> json) => Idea(
        ideaId: json['ideaId'] as String,
        boardId: json['boardId'] as String,
        state: IdeaState(json['state'] as String),
        title: json['title'] as String,
        description: json['description'] as String,
        format: json['format'] as String?,
        topic: json['topic'] as String?,
        proposer: Author.fromJson(json['proposer'] as Map<String, dynamic>),
        proposedAt: json['proposedAt'] as String,
        noteCount: json['noteCount'] as int,
        election: json['election'] == null
            ? null
            : IdeaElection.fromJson(json['election'] as Map<String, dynamic>),
        opening: json['opening'] == null
            ? null
            : IdeaOpening.fromJson(json['opening'] as Map<String, dynamic>),
        decision: json['decision'] == null
            ? null
            : IdeaDecision.fromJson(json['decision'] as Map<String, dynamic>),
      );

  final IdeaId ideaId;
  final BoardId boardId;
  final IdeaState state;
  final IdeaTitle title;
  final IdeaDescription description;
  final IdeaFormat? format;
  final Topic? topic;
  final Author proposer;
  final String proposedAt;

  /// Notes on the idea the caller may read.
  final int noteCount;

  /// Present once an election was opened for the idea.
  final IdeaElection? election;
  final IdeaOpening? opening;

  /// Present in `declined`, `merged`, `selected` and `notSelected`.
  final IdeaDecision? decision;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'ideaId': ideaId,
        'boardId': boardId,
        'state': state.value,
        'title': title,
        'description': description,
        if (format != null) 'format': format!,
        if (topic != null) 'topic': topic!,
        'proposer': proposer.toJson(),
        'proposedAt': proposedAt,
        'noteCount': noteCount,
        if (election != null) 'election': election!.toJson(),
        if (opening != null) 'opening': opening!.toJson(),
        if (decision != null) 'decision': decision!.toJson(),
      };
}

/// NoteState is a closed set of string values defined by this specification's schema.
///
/// An extension type rather than an enum: a value from a newer MINOR of this
/// specification must not crash the parse (SPEC §5.2), and an enum would throw on one.
/// Compare against the constants below, and treat anything else as unrecognised.
extension type const NoteState(String value) {
  static const NoteState visible = NoteState('visible');
  static const NoteState withdrawn = NoteState('withdrawn');
  static const NoteState hidden = NoteState('hidden');

  /// Every value this specification's schema permits.
  static const List<NoteState> values = <NoteState>[visible, withdrawn, hidden];
}

/// A note as one caller may see it. `text` is absent from a `withdrawn` or `hidden`
/// note for anyone but its author and the board's facilitators (VTI-BRD-021).
class Note {
  const Note({
    required this.noteId,
    required this.boardId,
    this.ideaId,
    required this.author,
    this.text,
    required this.createdAt,
    required this.state,
    this.hiddenReason,
  });

  /// Read this payload from a decoded JSON object.
  factory Note.fromJson(Map<String, dynamic> json) => Note(
        noteId: json['noteId'] as String,
        boardId: json['boardId'] as String,
        ideaId: json['ideaId'] as String?,
        author: Author.fromJson(json['author'] as Map<String, dynamic>),
        text: json['text'] as String?,
        createdAt: json['createdAt'] as String,
        state: NoteState(json['state'] as String),
        hiddenReason: json['hiddenReason'] as String?,
      );

  final NoteId noteId;
  final BoardId boardId;

  /// The idea the note is attached to; absent for a note on the board itself.
  final IdeaId? ideaId;
  final Author author;
  final NoteText? text;
  final String createdAt;
  final NoteState state;

  /// A `hidden` note's reason, shown to everyone who sees the note.
  final Reason? hiddenReason;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'noteId': noteId,
        'boardId': boardId,
        if (ideaId != null) 'ideaId': ideaId!,
        'author': author.toJson(),
        if (text != null) 'text': text!,
        'createdAt': createdAt,
        'state': state.value,
        if (hiddenReason != null) 'hiddenReason': hiddenReason!,
      };
}
